#!/usr/bin/env python3
"""
Referrals, end to end. Replaces add-find-help.py -- run this instead.

Someone can now ask for a person, practitioners see and offer on the requests
that match them, and the person chooses one. That is the whole transaction.

  the person       /find-help          ask, then read offers, then choose
                   Today               a card
                   More sheet          "Find a person"
                   /sos                one line underneath, never inside

  the practitioner /therapists/dashboard   matching requests, and an offer box
                                           people who chose them, with contact

  the rules        src/lib/referral-matching.ts

Four things that are load-bearing:

  Requests belong to the person who wrote them, and row-level security says so.
  The practitioner dashboard reads them with the service role and then filters
  in code -- and builds what it hands to the page field by field, so a column
  added later can never start leaking by accident.

  Contact details are released at exactly one moment: when the person chooses
  someone. Before that a practitioner sees what was asked for and what was
  written, and nothing that identifies anybody.

  Choosing one declines the rest in the same action, so nobody sits waiting on
  an answer that is not coming.

  Five offers per request, maximum. Someone who has just worked up the nerve to
  ask for help should not open the app to fifteen strangers competing for them.

No reviews and no ratings anywhere: the National Law prohibits testimonials for
regulated health services, and a match score would be a clinical claim nobody
here can make.

Nothing promises an email, because Mentara cannot send one yet. Both sides are
told plainly to check the page instead. When transactional email exists, that
copy is three strings in src/lib/referrals.ts, therapist-requests.tsx and
therapists/apply/page.tsx.

Run from anywhere:  python3 add-referrals.py
"""

import base64
import json
import sys
from pathlib import Path

BLOB = '{"src/lib/referrals.ts": "", "src/lib/referral-matching.ts": "", "src/app/api/referrals/route.ts": "", "src/app/api/referrals/accept/route.ts": "", "src/app/api/therapists/offers/route.ts": "", "src/components/find-help-form.tsx": "", "src/components/therapist-requests.tsx": "", "src/components/referral-offers.tsx": "", "src/app/(app)/find-help/page.tsx": "", "src/app/(app)/dashboard/page.tsx": "", "src/app/therapists/dashboard/page.tsx": "", "src/app/therapists/apply/page.tsx": "", "src/app/sos/page.tsx": "", "src/components/app-nav.tsx": "", "src/lib/supabase/middleware.ts": ""}'

FILES = json.loads(BLOB)


def find_repo() -> Path:
    seeds = [Path(__file__).resolve().parent, Path.cwd()]
    for seed in seeds:
        for root in [seed, *seed.parents]:
            if (root / "src" / "components" / "app-nav.tsx").is_file():
                return root
    sys.exit(
        "Could not find the repo above this script.\n"
        "Put this file inside ~/Documents/mentara-v2 and run it again."
    )


def main() -> None:
    root = find_repo()
    for rel, encoded in sorted(FILES.items()):
        path = root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        existed = path.is_file()
        path.write_bytes(base64.b64decode(encoded))
        print(f"  {'~' if existed else '+'} {rel}")
    print("\nThe database tables and policies are already live.")
    print("\nThen:")
    print('  git add -A && git commit -m "Referrals end to end"')
    print("  git push")


if __name__ == "__main__":
    main()
